<?php defined('ABSPATH')||exit; function bluprint_faq_defaults(){return ['enabled'=>1,'title'=>'سؤالات متداول'];} function bluprint_faq_register_post_type(){ register_post_type('bp_faq',[ 'labels'=>[ 'name'=>'سؤالات متداول', 'singular_name'=>'سؤال', 'add_new'=>'افزودن سؤال', 'add_new_item'=>'افزودن سؤال جدید', 'edit_item'=>'ویرایش سؤال', 'new_item'=>'سؤال جدید', 'view_item'=>'مشاهده سؤال', 'search_items'=>'جستجوی سؤال‌ها', 'not_found'=>'سؤالی پیدا نشد', 'menu_name'=>'سؤالات متداول' ], 'public'=>false, 'publicly_queryable'=>false, 'show_ui'=>true, 'show_in_menu'=>true, 'show_in_rest'=>true, 'menu_icon'=>'dashicons-editor-help', 'supports'=>['title','editor','page-attributes'], 'exclude_from_search'=>true, 'has_archive'=>false, 'rewrite'=>false, 'query_var'=>false ]); }
add_action('init','bluprint_faq_register_post_type'); function bluprint_faq_sanitize($input){ $input=is_array($input)?$input:[]; return [ 'enabled'=>empty($input['enabled'])?0:1, 'title'=>sanitize_text_field($input['title']??'') ]; }
function bluprint_faq_register_settings(){ register_setting('bluprint_faq_group','bluprint_faq_section',[ 'type'=>'array', 'sanitize_callback'=>'bluprint_faq_sanitize', 'default'=>bluprint_faq_defaults() ]); }
add_action('admin_init','bluprint_faq_register_settings'); function bluprint_faq_add_settings_page(){ add_submenu_page( 'bluprint-settings', 'تنظیمات سکشن FAQ', 'تنظیمات سکشن', 'edit_theme_options', 'bluprint-faq-settings', 'bluprint_faq_settings_page' ); }
add_action('admin_menu','bluprint_faq_add_settings_page'); function bluprint_faq_settings_page(){ if(!current_user_can('edit_theme_options'))return; $data=wp_parse_args(get_option('bluprint_faq_section',[]),bluprint_faq_defaults()); ?> <div class="wrap"> <h1>تنظیمات سؤالات متداول</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_faq_group'); ?> <table class="form-table" role="presentation"> <tr> <th scope="row">وضعیت سکشن</th> <td> <label> <input type="checkbox" name="bluprint_faq_section[enabled]" value="1" <?php checked($data['enabled'],1); ?>> نمایش سؤالات متداول در صفحه اصلی </label> </td> </tr> <tr> <th scope="row"><label for="bluprint-faq-title">عنوان سکشن</label></th> <td> <input id="bluprint-faq-title" class="regular-text" type="text" name="bluprint_faq_section[title]" value="<?php echo esc_attr($data['title']); ?>"> </td> </tr> </table> <?php submit_button('ذخیره تنظیمات'); ?> </form> </div> <?php }
function bluprint_get_faq_data(){ return wp_parse_args(get_option('bluprint_faq_section',[]),bluprint_faq_defaults()); }
function bluprint_get_faq_items(){ return get_posts([ 'post_type'=>'bp_faq', 'post_status'=>'publish', 'posts_per_page'=>-1, 'orderby'=>['menu_order'=>'ASC','date'=>'ASC'], 'order'=>'ASC', 'no_found_rows'=>true ]); }
function bluprint_faq_admin_assets($hook){ if($hook!=='edit.php'||($_GET['post_type']??'')!=='bp_faq')return; wp_enqueue_script('jquery-ui-sortable'); wp_enqueue_script( 'bluprint-faq-sort', get_theme_file_uri('assets/js/admin/faq-sort.js'), ['jquery','jquery-ui-sortable'], bluprint_asset_version('assets/js/admin/faq-sort.js'), true ); wp_localize_script('bluprint-faq-sort','bluprintFaqSort',[ 'ajaxUrl'=>admin_url('admin-ajax.php'), 'nonce'=>wp_create_nonce('bluprint_faq_sort'), 'message'=>'ترتیب سؤالات ذخیره شد.' ]); }
add_action('admin_enqueue_scripts','bluprint_faq_admin_assets'); function bluprint_faq_admin_order($query){ if(!is_admin()||!$query->is_main_query())return; if($query->get('post_type')!=='bp_faq')return; $query->set('posts_per_page',-1); $query->set('orderby',['menu_order'=>'ASC','date'=>'ASC']); $query->set('order','ASC'); }
add_action('pre_get_posts','bluprint_faq_admin_order'); function bluprint_faq_sort_ajax(){ if(!current_user_can('edit_posts'))wp_send_json_error(['message'=>'دسترسی غیرمجاز.'],403); check_ajax_referer('bluprint_faq_sort','nonce'); $ids=isset($_POST['order'])?array_map('absint',(array)wp_unslash($_POST['order'])):[]; $ids=array_values(array_unique(array_filter($ids))); foreach($ids as $position=>$id){ if(get_post_type($id)!=='bp_faq')continue; wp_update_post([ 'ID'=>$id, 'menu_order'=>$position ]); } wp_send_json_success(['message'=>'ترتیب سؤالات ذخیره شد.']); }
add_action('wp_ajax_bluprint_faq_sort','bluprint_faq_sort_ajax'); function bluprint_faq_admin_row_class($classes,$class,$post_id){ if(get_post_type($post_id)==='bp_faq')$classes[]='bluprint-faq-sortable'; return $classes; }
add_filter('post_class','bluprint_faq_admin_row_class',10,3);